mapper.update:
UPDATE subscriptions
SET status = 'PAST_DUE',
    past_due_at = #{pastDueAt},
    next_billing_at = NULL,
    version = #{nextVersion}
WHERE id = #{id}
  AND status = 'ACTIVE'
  AND current_period_end IS NOT NULL
  AND current_period_end <= #{pastDueAt}

UPDATE subscriptions
SET status = 'EXPIRED',
    expired_at = #{expiredAt},
    next_billing_at = NULL,
    version = #{nextVersion}
WHERE id = #{id}
  AND status = 'CANCELED'
  AND current_period_end <= #{expiredAt}

UPDATE subscriptions
SET status = 'EXPIRED',
    expired_at = #{expiredAt},
    next_billing_at = NULL,
    version = #{nextVersion}
WHERE id = #{id}
  AND status = 'PAST_DUE'
  AND past_due_at IS NOT NULL
  AND past_due_at <= #{cutoff}
